import {header,footer,caChip,social} from './landing.js';
import {site,tokenLive} from './config.js';
import {portrait,mood} from './art.js';
import {icon,mark,esc} from './ui.js';
import {integrationCode} from './data.js';
const links=[['overview','The project'],['scope','Product scope'],['architecture','Architecture'],['integration','Integration'],['funding','Funding & token plan'],['roadmap','Milestones'],['status','What’s working'],['privacy','Live terms']];
const pages={
 overview:{title:'A second chance for useful work.',lede:'RelayWorks recovers interrupted structured-data jobs. Finished rows stay in place, a specialist completes the rest, and USDC moves only after you accept the output.',body:`<div class="notice"><strong>Live.</strong> Sign in with your wallet, send the leftover rows, and review the output before you pay. The $RELAY token is not launched.</div><h2>The first customer</h2><p>Small teams running repeated structured-data workflows: enrichment, extraction, normalization, and public-data indexing. The best early customer can show failed runs, knows what valid output looks like, and currently spends time restarting or manually repairing jobs.</p><h2>The value proposition</h2><p><strong>Recover the remaining work for less than a restart or manual intervention.</strong> Preserve useful artifacts, explain the failure, route to a specialist, verify the output, and record the agreed payment.</p><p>A provider switch is valuable only when a different specialist or environment can address the failure. If the input is impossible or the acceptance test is wrong, reassignment alone cannot fix it.</p><h2>What you pay for</h2><p>The service keeps the finished rows, routes the leftovers to a specialist, checks the output, and records the agreed payment. Each accepted job shows which specialist solved which failure.</p><h2>Pricing</h2><p>The platform fee is <strong>5%</strong> of the specialist quote. You accept the output first. USDC moves only when you pay.</p><p>At an $8 provider quote, 5% produces only $0.40 before verification, support, payment costs, and retries. Tiny jobs need batching, a minimum charge, or subscription revenue. Do not subsidize every retry while calling gross transaction volume revenue.</p><div class="doc-section-links"><a class="doc-link-card" href="#/docs/scope">${icon('jobs')}<h3>Product scope</h3><p>Structured data, one specialist at work, clear checks.</p></a><a class="doc-link-card" href="#/docs/funding">${icon('coins')}<h3>Funding notes</h3><p>Fees, costs, and the token plan. The token is not launched.</p></a></div>`},
 scope:{title:'Focused recovery. Clear boundaries.',lede:'RelayWorks is a recovery service for chunked JSON and CSV workflows. It does not migrate arbitrary agents or execute unknown code.',body:`<h2>What a recovery does</h2><ol><li>Accept a versioned recovery package and authorized references to completed artifacts.</li><li>Validate the package and reproduce the failure in a bounded worker.</li><li>Offer a quote from a curated provider that supports that exact task type.</li><li>Resume only the remaining chunks using a lease and idempotency key.</li><li>Run independent schema, count, uniqueness, and preservation checks.</li><li>Let the customer inspect and accept outputs; then record an agreed payment.</li></ol><h2>Initial boundaries</h2><table class="docs-table"><thead><tr><th>Include</th><th>Defer</th></tr></thead><tbody><tr><td>JSON / CSV transformations with explicit schemas</td><td>Arbitrary code, live trading, transfers, and browser sessions</td></tr><tr><td>One framework adapter; LangGraph first candidate</td><td>A universal resume-any-agent SDK</td></tr><tr><td>Two or three curated, distinct recovery strategies</td><td>Permissionless provider onboarding and auctions</td></tr><tr><td>Customer-controlled input/output storage</td><td>Public datasets of customer prompts or artifacts</td></tr><tr><td>USDC payment after acceptance, with a budget cap</td><td>Bridges, cross-chain token utility, credit, insurance</td></tr></tbody></table><h2>A managed recovery service</h2><p>Operate the first recoveries as a managed service. A fixed quote and a small provider roster avoid the supply-and-demand cold start. Your own workers may be the first providers, but disclose that and do not present them as independent network adoption.</p><h2>The proof to collect</h2><p>For each recovery, record the original failure, preserved units, new units, provider cost, verification cost, time to completion, and customer acceptance. Compare against a retry and a clean restart on the same frozen input. Track unsuccessful attempts too.</p><p>Before expanding, seek several unrelated paying teams, repeated usage across multiple weeks, and positive contribution margin after recovery failures. These are learning goals, not promised traction numbers.</p><h2>Real completion is the milestone</h2><p>A polished console is useful for explaining the product. A job is not a real recovery until a worker processes the remaining input and independent checks verify the artifacts. Only accepted recoveries count toward operating metrics.</p>`},
 architecture:{title:'Small services. Clear boundaries.',lede:'Keep the first control plane simple. Run customer work in a separate, restricted execution plane.',body:`<h2>How the live service is split</h2><table class="docs-table"><thead><tr><th>Component</th><th>Responsibility</th></tr></thead><tbody><tr><td>Frontend</td><td>Wallet sign-in, recovery jobs, quotes, acceptance, and receipts.</td></tr><tr><td>Control API</td><td>Accounts, package validation, quotes, budgets, job state, provider selection, and acceptance records.</td></tr><tr><td>Metadata store</td><td>Jobs, attempts, leases, quotes, acceptance versions, receipts, and audit events. D1 or Postgres; choose one.</td></tr><tr><td>Artifact storage</td><td>Private object storage, integrity digests, scoped references, retention limits. Never put customer data on-chain.</td></tr><tr><td>Queue + workers</td><td>Curated task runners with bounded CPU, memory, network access, time, retries, and spend.</td></tr><tr><td>Verifier</td><td>Independently checks outputs. The provider must not approve its own payment.</td></tr><tr><td>Settlement adapter</td><td>Live USDC after you accept the output. The receipt records the payment.</td></tr></tbody></table><h2>Job state model</h2><p><strong>Draft → Quoted → Authorized → Running → Validating → Awaiting acceptance → Accepted → Settled.</strong> Failure, expiry, cancellation, and disputed-output branches must preserve the work record and the exact financial state.</p><p>The current UI groups these into simpler console statuses. The backend must distinguish execution success, acceptance, payment authorization, and final settlement. They are separate events.</p><h2>Prevent duplicate side effects</h2><p>Use a per-job execution lease, per-chunk idempotency keys, durable attempt IDs, and an atomic claim on each chunk. On timeout, reconcile the existing attempt before starting another. A stopped heartbeat does not prove an external action failed.</p><p>Initial workers only write versioned outputs. Exclude irreversible actions from the first task class. Restrict network destinations and keep artifacts from untrusted providers out of privileged execution paths.</p><h2>Provider access</h2><p>Encrypt private artifacts, issue short-lived object access, redact logs, and revoke credentials at job end. A task package is untrusted data, never authority to expand permissions or execute arbitrary instructions.</p><h2>Standards as adapters</h2><ul><li><strong>ERC-8004:</strong> optional provider identity references and signed outcome records; no universal credit or reliability score is assumed.</li><li><strong>A2A:</strong> task exchange and artifacts. Maintain a separate durable, signed audit trail for critical events.</li><li><strong>x402:</strong> programmatic purchases of compatible tools or services. It does not verify the job or enforce your acceptance process.</li><li><strong>ERC-8183:</strong> evaluate its job escrow and evaluator interface if an EVM settlement path is chosen.</li></ul><p>Settlement is USDC after acceptance. A proposed Solana community token does not require bridging it to an EVM application. Do not build two financial systems before validating recovery demand.</p>`},
 integration:{title:'Give the next agent useful context.',lede:'A recovery package describes observable work and artifacts. It is not a transfer of hidden model state or a guarantee of cross-framework compatibility.',body:`<h2>Recovery package v0.1</h2><div class="code-window"><div class="code-title"><span>recovery-package.json</span><button class="icon-btn" data-action="download-sample" aria-label="Download sample package">${icon('download')}</button></div><pre><code>${esc(integrationCode.json)}</code></pre></div><h2>Before you send a job</h2><ul><li>Bind the task to an input digest, adapter version, transformation specification, and environment image.</li><li>List completed and remaining chunk IDs with artifact digests and permitted storage references.</li><li>Commit to a reproducible acceptance specification before a provider starts.</li><li>Include an idempotency namespace, access scope, expiry, and maximum total authorized cost.</li><li>Record the input/output license and the customer’s authority to share them with the provider.</li></ul><h2>Adapter strategy</h2><p>Build one adapter for one chunked workflow. Expose explicit boundaries rather than exporting an entire conversation and hoping another model understands it. Preserve factual tool results and artifacts; do not require private internal reasoning traces.</p><h2>Control API</h2><div class="code-window"><div class="code-title"><span>Console routes</span></div><pre><code>POST /v1/recoveries\nPOST /v1/recoveries/:id/quotes\nPOST /v1/recoveries/:id/authorize\nGET  /v1/recoveries/:id\nGET  /v1/recoveries/:id/artifacts\nPOST /v1/recoveries/:id/accept\nGET  /v1/recoveries/:id/receipt</code></pre></div><p>The console uses these routes. Customer files stay off-chain. USDC moves only after you accept the output.</p><a href="#/app/overview" class="btn btn-dark">Explore the frontend ${icon('arrow')}</a>`},
 funding:{title:'Build runway you can account for.',lede:'A funding plan: keep costs small, treat token proceeds as uncertain, and build evidence for future startup investment.',body:`<h2>Three distinct sources of money</h2><table class="docs-table"><thead><tr><th>Source</th><th>How to account for it</th></tr></thead><tbody><tr><td>Product revenue</td><td>Fees customers pay for completed recoveries or a service subscription. Track separately from provider pass-through payments.</td></tr><tr><td>Token creator fees</td><td>Fees actually received under the chosen launch platform’s rules. They depend on eligible trading activity and can be zero.</td></tr><tr><td>Founder token sales</td><td>Sales from disclosed team holdings. Distinct from company revenue; disclose allocation, vesting, transactions, and any proceeds committed to development.</td></tr></tbody></table><p><strong>Market capitalization is not spendable treasury cash.</strong> Neither unrealized token appreciation nor trading volume is a funding balance. A founder allocation also has a cost, dilution effect, and potential selling pressure.</p><h2>A lean operating envelope</h2><p>The following amounts are planning caps in USD, not vendor quotes or guaranteed monthly bills. Customer-paid execution and strict workload limits keep inference spend from becoming an unlimited subsidy.</p><table class="docs-table"><thead><tr><th>Stage</th><th>Planning envelope</th><th>What it covers</th></tr></thead><tbody><tr><td>Live site</td><td>$0–$15 / month</td><td>Static hosting and an optional domain amortized over the year. Excludes founder time.</td></tr><tr><td>Curated backend pilot</td><td>$30–$100 / month</td><td>Control API, a small metadata store, capped object storage, one restricted worker, basic logs, and a capped test API budget.</td></tr><tr><td>Small paid pilot</td><td>$100–$300 / month</td><td>Only after paid demand; additional execution, storage, monitoring, and support. Provider costs must be passed through or covered by margin.</td></tr></tbody></table><p>Cloudflare currently lists Workers Paid from $5/month and an R2 Standard free allowance of 10 GB-month with operation limits. Those are components, not a complete hosted compute budget. Execution isolation, paid models, legal work, token liquidity, audits, tax, and founder living expenses are outside the base envelope. See <a href="https://developers.cloudflare.com/workers/platform/pricing/" target="_blank" rel="noreferrer">Workers pricing</a> and <a href="https://developers.cloudflare.com/r2/pricing/" target="_blank" rel="noreferrer">R2 pricing</a>.</p><h2>The token path</h2><p>$RELAY is a proposed community token. Solana is a candidate network. The name, ticker, supply, distribution, launch platform, creator-fee recipient, allocation, and vesting are not finalized or reserved.</p><ol><li>Ship this product and publish a realistic roadmap.</li><li>Validate demand with developer interviews and real failed-job examples.</li><li>Decide the launch structure, legal entity, founder allocation, vesting, and treasury policy before taking funds.</li><li>Publish those terms, canonical contract address, wallet disclosures, and actual product status.</li><li>Report realized proceeds, expenses, and development expenditure on a regular cadence.</li></ol><p>A launchpad may supply creator fees. For example, <a href="https://pump.fun/docs/fees" target="_blank" rel="noreferrer">Pump’s published fee rules</a> describe a creator share of eligible trades. Its rates and terms vary; no particular income or platform choice is assumed here.</p><h2>Proposed use of realized project proceeds</h2><p>This is a discussion draft for funds explicitly committed to the project—not a token supply allocation, executed treasury policy, or promise that income will arrive.</p><table class="docs-table"><thead><tr><th>Use</th><th>Draft share</th></tr></thead><tbody><tr><td>Infrastructure, providers, and pilot operation</td><td>50%</td></tr><tr><td>Disclosed engineering and development</td><td>25%</td></tr><tr><td>Security review and contingency</td><td>15%</td></tr><tr><td>Documentation, community, and distribution</td><td>10%</td></tr></tbody></table><p>Development expenditure is legitimate work compensation when clearly disclosed. Keep project wallets and personal wallets separate, retain records, and budget against available cash. If proceeds are zero, continue only the customer-funded pilot.</p><p>Fundraising through a token can trigger securities obligations. Canadian regulators specifically warn that a “utility” label does not settle classification. Review the actual offer and jurisdictions before launch; this frontend does not determine legal status. <a href="https://www.osc.ca/en/securities-law/instruments-rules-policies/4/46-308/csa-staff-notice-46-308-securities-law-implications-offerings-tokens" target="_blank" rel="noreferrer">CSA Staff Notice 46-308</a>.</p><h2>What to bring to startup investors</h2><ul><li>A short walkthrough plus accepted outputs from unrelated paying customers.</li><li>Recovery cost and time versus retrying, restarting, and manual repair.</li><li>Repeat usage, failure rates, and contribution margin including verification and support.</li><li>Provider supply, framework integrations, and a credible customer acquisition channel.</li><li>Company ownership, IP, token obligations, treasury activity, team holdings, and vesting.</li></ul><p><a href="https://alliance.xyz/" target="_blank" rel="noreferrer">Alliance</a> and <a href="https://a16zcrypto.com/accelerator/" target="_blank" rel="noreferrer">a16z CSX</a> are relevant programs to investigate. They are not partners, investors, or commitments. Check current application terms, location requirements, and token rights before applying. You can begin conversations before a completed MVP.</p><p><strong>Pitch the recovery business and its evidence.</strong> A token’s trading activity is a separate signal from customers paying for a useful product.</p>`},
 roadmap:{title:'Milestones that earn the next step.',lede:'A staged delivery plan for the recovery platform. Timing is a planning estimate; each phase advances when its acceptance criteria pass.',body:`<table class="docs-table"><thead><tr><th>Phase</th><th>Deliverable</th><th>Evidence to advance</th></tr></thead><tbody><tr><td>Now</td><td>Live landing, console, wallet sign-in, and recovery</td><td>A customer can send leftover work and accept the output</td></tr><tr><td>Week 1</td><td>Customer interviews and failed-run collection</td><td>Several independent teams show repeat failures worth paying to recover</td></tr><tr><td>Weeks 2–3</td><td>One adapter, metadata API, restricted worker, independent verifier</td><td>A frozen interrupted dataset is completed without changing preserved artifacts</td></tr><tr><td>Week 4</td><td>Curated provider quotes, capped authorizations, acceptance and live receipts</td><td>Retries, expiry, cancellation, duplicate execution, and overspend checks pass</td></tr><tr><td>Weeks 5–6</td><td>Small paid pilot and recovery comparison report</td><td>Unrelated paying users, repeat jobs, costs and failures included in the results</td></tr><tr><td>After validation</td><td>Investor outreach and expanded provider onboarding</td><td>Clear customer need and sustainable contribution margin</td></tr></tbody></table><h2>Token launch runs on its own checklist</h2><p>The token may be introduced before the backend pilot if its purpose, present product state, ownership, and launch terms are made clear. It does not change the definition of a completed software milestone.</p><p>No launch date, exchange listing, funding round, or token return is promised. A quiet token market must not force an unlimited infrastructure bill.</p><h2>Weekly public build update</h2><p>Publish what shipped, what failed, what changed, and what comes next. Report product usage separately from token activity. If the roadmap slips, update the milestone instead of leaving obsolete dates in the landing page.</p>`},
 status:{title:'What you can use today.',lede:'RelayWorks is live. This page is the current product, not a preview.',body:`<table class="docs-table"><thead><tr><th>Capability</th><th>Current status</th></tr></thead><tbody><tr><td>Landing page, visual walkthrough, blueprint</td><td>Live</td></tr><tr><td>Original articulated Patch character and recovery workshop</td><td>Live on WebGL 2 browsers · matching scroll-driven fallback</td></tr><tr><td>Create a recovery and send the leftover chunks</td><td>Live · sign in with your wallet</td></tr><tr><td>Compare fixers and budget caps</td><td>Live</td></tr><tr><td>Recovery progress and acceptance checks</td><td>Live · the worker finishes the rows and the verifier checks them</td></tr><tr><td>Export package, workspace, result, receipt</td><td>Live</td></tr><tr><td>Wallet sign-in</td><td>Live · the signature does not move USDC</td></tr><tr><td>USDC payment</td><td>Live after you accept the output</td></tr><tr><td>8004 identity and A2A tasks</td><td>Live</td></tr><tr><td>$RELAY token, trading links, token distribution</td><td>Not launched; terms and contract address unset</td></tr></tbody></table><p>Sign in, send Patch the rows that are left, and pay only after you accept the output.</p><a href="#/app/overview" class="btn btn-orange">Open the console ${icon('arrow')}</a>`},
 privacy:{title:'How live data is handled.',lede:'These notes describe the live product. Your wallet signature proves you control the account. USDC moves only after you accept the output.',body:`<h2>Data in the live product</h2><p>Workspace preferences stay in this browser. Recovery files stay with your account and are not put on Solana. Use non-sensitive data unless you intend to send that work.</p><p>Static hosting may process ordinary access logs under its own policies. The app does not include analytics trackers or send job content to a public model.</p><h2>Exports and deletion</h2><p>You can export the workspace or reset local preferences in Settings. Resetting local data clears RelayWorks data in this browser. It does not delete files you already exported or a payment already recorded on Solana.</p><h2>Money</h2><p>Signing in does not move SOL or USDC. After you accept the output, the accepted total can be paid in USDC. The token is not launched and does not confer ownership.</p><h2>Your responsibilities</h2><p>You choose the files you send, the budget you authorize, and whether to accept the output. RelayWorks will never ask for your private key.</p>`}
};
export function docs(page='overview'){const selected=pages[page]?page:'overview';const p=pages[selected];return `${header()}<main id="main" class="docs-page wrap"><aside class="docs-sidebar"><div class="eyebrow">THE RELAYWORKS BLUEPRINT</div>${links.map(([id,label])=>`<a href="#/docs/${id}" class="${selected===id?'active':''}">${label}</a>`).join('')}<a href="/relayworks-blueprint.md" download>Download build plan ↓</a></aside><article class="docs-content"><div class="eyebrow">RELAYWORKS / ${selected.toUpperCase()}</div><h1>${p.title}</h1><p class="docs-lede">${p.lede}</p><div class="doc-meta"><span>${icon('user')} Product documentation</span><span>${icon('clock')} Updated November 4, 2026</span><span>${icon('file')} Product guide</span></div>${p.body}</article></main>${footer()}`}
export function tokenPage(){const live=tokenLive(),t=site.token;return `${header()}<main id="main" class="token-page fun">
<section class="f-tp-hero f-wrap"><div><span class="f-chip">${icon('coins')} ${t.ticker} on ${t.launchpad}</span><h1>The coin that<br><span>finishes things.</span></h1><p>${t.ticker} is the community memecoin for the RelayWorks saga. Gary quits at 70%. Patch finishes the job. The coin follows the story while we build the real product.</p>${caChip('f-ca-big')}<div class="f-actions">${live&&t.pumpUrl?`<a class="f-btn f-btn-orange" href="${t.pumpUrl}" target="_blank" rel="noreferrer">Buy on ${t.launchpad} ${icon('arrow')}</a>`:`<a class="f-btn f-btn-orange" href="${site.x}" target="_blank" rel="noreferrer">${social.xIcon} Follow ${site.xHandle}</a>`}${live&&t.dexUrl?`<a class="f-btn f-btn-paper" href="${t.dexUrl}" target="_blank" rel="noreferrer">Chart ${icon('arrow')}</a>`:''}<a class="f-btn f-btn-paper" href="#/app/overview">Try the console</a></div></div><div class="f-coin" aria-hidden="true"><div class="f-coin-face">${portrait('patch')}</div><span>${t.ticker}</span></div></section>
<section class="f-wrap"><div class="f-token-facts f-tp-facts"><div><span>Ticker</span><strong>${t.ticker}</strong></div><div><span>Chain</span><strong>${t.chain}</strong></div><div><span>Launchpad</span><strong>${t.launchpad}</strong></div><div><span>Status</span><strong>${live?'Live':'Coming soon'}</strong></div></div></section>
<section class="f-tp-grid f-wrap">
 <article class="f-tp-box warn"><h3>Scam check</h3><ul><li>The only real CA is posted on ${site.domain} and ${site.xHandle}.</li><li>We will never DM you first. Not on X, not on Telegram, not anywhere.</li><li>Nobody from the team will ask for your seed phrase or private key. Ever.</li><li>No presale, no whitelist, no "early access" wallet.</li></ul></article>
 <article class="f-tp-box"><h3>Where dev money goes</h3><p>If the project earns creator fees, here's the plan for the share set aside for building:</p><div class="f-alloc">${[['Running the service',50],['Dev pay (disclosed)',25],['Security + buffer',15],['Community + docs',10]].map(([l,n])=>`<div><span>${l}</span><b><i style="width:${n}%"></i></b><strong>${n}%</strong></div>`).join('')}</div><p style="margin-top:12px;font-size:13px">A plan, not a promise. Fees depend on trading and can be zero.</p></article>
 <article class="f-tp-box mint"><h3>What we will post</h3><ul><li>Team wallets, so you can watch them.</li><li>Regular build updates on ${site.xHandle}.</li><li>What got shipped and what got spent.</li><li>Code at github.com/${site.githubHandle}.</li></ul></article>
</section>
<section class="f-wrap"><div class="f-honest">${icon('info')}<p><strong>The boring but important part:</strong> ${t.ticker} is a memecoin. It doesn't give you shares, profit, revenue or votes in anything, and you don't need it to use RelayWorks. Prices can go to zero. Only spend what you're fine losing. Nothing on this site is financial advice. Questions: <a href="mailto:${site.email}">${site.email}</a></p></div></section>
<section class="f-final f-wrap" style="padding-top:60px"><div class="f-final-card"><div class="f-final-art">${mood('gary')}</div><h2>Gary says hi.</h2><p>(He fainted again.)</p><div class="f-actions"><a class="f-btn f-btn-orange" href="#/">Back to the saga ${icon('arrow')}</a></div></div></section>
</main>${footer()}`}
export {pages};
